import React from 'react';
import { CanvasRenderer } from './CanvasRenderer';
import { ElementLayer } from './ElementLayer';
import { ElementEditLayer } from './ElementEditLayer';
import { TextLayer } from './TextLayer';
import { TextEditLayer } from './TextEditLayer';
import { DimensionLayer } from './DimensionLayer';
import { RegionLayer } from './RegionLayer';
import { StairLayer } from './StairLayer';
import { StairEditLayer } from './StairEditLayer';
import { NorthArrowLayer } from './NorthArrowLayer';
import { NorthArrowEditLayer } from './NorthArrowEditLayer';
import { ClipFrameLayer } from './ClipFrameLayer';
import { ClipFrameEditLayer } from './ClipFrameEditLayer';
import { AxisEditLayer } from './AxisEditLayer';
import { StairElementLayer } from './StairElementLayer';
import { StairElementEditLayer } from './StairElementEditLayer';
import type { Wall, CanvasView, Column, Window, Door, Opening, TextElement, Stair, NorthArrow, ClipFrame, PlanImage, Axis, StairElement, AppMode, RoundedCorner } from '../../core/types';
import type { Dimension } from '../../core/dimensionTypes';
import type { RoomRegion } from '../../core/regionTypes';

interface Props {
  walls: Wall[]; windows: Window[]; doors: Door[]; view: CanvasView; width: number; height: number;
    selectedWallId: string | null; tempStart: { x: number; y: number } | null; tempEnd: { x: number; y: number } | null;
      columns: Column[]; texts: TextElement[]; regions: RoomRegion[]; stairs: Stair[]; northArrows: NorthArrow[]; clipFrames: ClipFrame[];
        openings?: Opening[];
          axes: Axis[]; 
            selectedStairId: string | null; 
              // ✅ تصحيح النوع ليشمل الفتحة
                selectedElement: { id: string; type: 'column' | 'window' | 'door' | 'opening' } | null;
                  selectedTextId: string | null; selectedNorthArrowId: string | null; selectedClipFrameId: string | null; selectedAxisId: string | null;
                    dimensions: Dimension[]; dimensionFontSize: number; selectedDimId: string | null; scale?: number; planImage?: PlanImage | null;
                      showGrid?: boolean;
                        axisBubbleSize?: number;
                          stairElements: StairElement[];
                            selectedStairElementId: string | null;
                              activeFloor?: number;
                                showPreviousFloor?: boolean;
                                  mode?: AppMode;
                                    roundCornerFirstWallId?: string | null;
                                      roundedCorners?: RoundedCorner[];
                                        pendingRoundedCorner?: { wallAId: string; wallBId: string; radius: number; } | null;
                                          selectedRoundedCornerId?: string | null;
                                            joinWallsPendingIds?: string[];
                                              contourHighlightIds?: string[];
                                              }

                                              export const CanvasLayers: React.FC<Props> = React.memo((props) => {
                                                const {
                                                    walls, windows, doors, openings = [], view, width, height,
                                                        selectedWallId, tempStart, tempEnd,
                                                            columns, texts, regions, stairs, northArrows, clipFrames, axes,
                                                                selectedStairId, selectedElement,
                                                                    selectedTextId, selectedNorthArrowId, selectedClipFrameId, selectedAxisId,
                                                                        dimensions, dimensionFontSize, selectedDimId,
                                                                            scale = 1, planImage = null, showGrid = true, axisBubbleSize = 11,
                                                                                stairElements, selectedStairElementId,
                                                                                    activeFloor = 0,
                                                                                        showPreviousFloor = false,
                                                                                            mode = 'view',
                                                                                                roundCornerFirstWallId = null, roundedCorners = [],
                                                                                                    pendingRoundedCorner = null,
                                                                                                        selectedRoundedCornerId = null,
                                                                                                            joinWallsPendingIds = [],
                                                                                                                contourHighlightIds = [],
                                                                                                                  } = props;

                                                                                                                    // ✅ فلترة العناصر حسب الدور النشط
                                                                                                                      const filteredColumns = React.useMemo(() => columns.filter(c => (c.floor ?? 0) === activeFloor), [columns, activeFloor]);
                                                                                                                        const filteredWindows = React.useMemo(() => windows.filter(w => (w.floor ?? 0) === activeFloor), [windows, activeFloor]);
                                                                                                                          const filteredDoors = React.useMemo(() => doors.filter(d => (d.floor ?? 0) === activeFloor), [doors, activeFloor]);
                                                                                                                            const filteredOpenings = React.useMemo(() => openings.filter(o => (o.floor ?? 0) === activeFloor), [openings, activeFloor]);
                                                                                                                              const filteredTexts = React.useMemo(() => texts.filter(t => (t.floor ?? 0) === activeFloor), [texts, activeFloor]);
                                                                                                                                const filteredDimensions = React.useMemo(() => dimensions.filter(d => (d.floor ?? 0) === activeFloor), [dimensions, activeFloor]);
                                                                                                                                  const filteredRegions = React.useMemo(() => regions.filter(r => (r.floor ?? 0) === activeFloor), [regions, activeFloor]);
                                                                                                                                    const filteredStairs = React.useMemo(() => stairs.filter(s => (s.floor ?? 0) === activeFloor), [stairs, activeFloor]);
                                                                                                                                      const filteredStairElements = React.useMemo(() => stairElements.filter(el => (el.floor ?? 0) === activeFloor), [stairElements, activeFloor]);
                                                                                                                                        const filteredAxes = React.useMemo(() => axes.filter(a => (a.floor ?? 0) === activeFloor), [axes, activeFloor]);

                                                                                                                                          // ✅ عناصر الدور السابق (Ghost)
                                                                                                                                            const showGhost = showPreviousFloor && activeFloor > 0;
                                                                                                                                              const ghostFloorNum = activeFloor - 1;

                                                                                                                                                const ghostColumns = React.useMemo(() => showGhost ? columns.filter(c => (c.floor ?? 0) === ghostFloorNum) : [], [columns, ghostFloorNum, showGhost]);
                                                                                                                                                  const ghostWindows = React.useMemo(() => showGhost ? windows.filter(w => (w.floor ?? 0) === ghostFloorNum) : [], [windows, ghostFloorNum, showGhost]);
                                                                                                                                                    const ghostDoors = React.useMemo(() => showGhost ? doors.filter(d => (d.floor ?? 0) === ghostFloorNum) : [], [doors, ghostFloorNum, showGhost]);
                                                                                                                                                      const ghostOpenings = React.useMemo(() => showGhost ? openings.filter(o => (o.floor ?? 0) === ghostFloorNum) : [], [openings, ghostFloorNum, showGhost]);
                                                                                                                                                        const ghostTexts = React.useMemo(() => showGhost ? texts.filter(t => (t.floor ?? 0) === ghostFloorNum) : [], [texts, ghostFloorNum, showGhost]);
                                                                                                                                                          const ghostDimensions = React.useMemo(() => showGhost ? dimensions.filter(d => (d.floor ?? 0) === ghostFloorNum) : [], [dimensions, ghostFloorNum, showGhost]);
                                                                                                                                                            const ghostRegions = React.useMemo(() => showGhost ? regions.filter(r => (r.floor ?? 0) === ghostFloorNum) : [], [regions, ghostFloorNum, showGhost]);
                                                                                                                                                              const ghostStairs = React.useMemo(() => showGhost ? stairs.filter(s => (s.floor ?? 0) === ghostFloorNum) : [], [stairs, ghostFloorNum, showGhost]);
                                                                                                                                                                const ghostStairElements = React.useMemo(() => showGhost ? stairElements.filter(el => (el.floor ?? 0) === ghostFloorNum) : [], [stairElements, ghostFloorNum, showGhost]);

                                                                                                                                                                  return (
                                                                                                                                                                      <>
                                                                                                                                                                            {/* ✅ عناصر الدور السابق — شفافة وغير قابلة للتفاعل */}
                                                                                                                                                                                  {showGhost && (
                                                                                                                                                                                          <div style={{ position: 'absolute', inset: 0, opacity: 0.3, pointerEvents: 'none' }}>
                                                                                                                                                                                                    {(ghostColumns.length > 0 || ghostWindows.length > 0 || ghostDoors.length > 0 || ghostOpenings.length > 0) && (
                                                                                                                                                                                                                <ElementLayer
                                                                                                                                                                                                                              columns={ghostColumns}
                                                                                                                                                                                                                                            windows={ghostWindows}
                                                                                                                                                                                                                                                          doors={ghostDoors}
                                                                                                                                                                                                                                                                        openings={ghostOpenings} // ✅ تمرير الفتحات الشبحية
                                                                                                                                                                                                                                                                                      selectedElement={null}
                                                                                                                                                                                                                                                                                                    walls={walls}
                                                                                                                                                                                                                                                                                                                  view={view}
                                                                                                                                                                                                                                                                                                                                width={width}
                                                                                                                                                                                                                                                                                                                                              height={height}
                                                                                                                                                                                                                                                                                                                                                            scale={scale}
                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                            {ghostTexts.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                        <TextLayer texts={ghostTexts} view={view} width={width} height={height} selectedId={null} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                            {ghostDimensions.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                        <DimensionLayer dimensions={ghostDimensions} view={view} width={width} height={height} fontSize={dimensionFontSize} selectedId={null} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                            {ghostRegions.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <RegionLayer regions={ghostRegions} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {ghostStairs.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <StairLayer stairs={ghostStairs} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {ghostStairElements.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <StairElementLayer stairElements={ghostStairElements} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <CanvasRenderer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              walls={walls}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      view={view}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width={width}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      height={height}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              selectedId={selectedWallId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tempStart={tempStart}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              tempEnd={tempEnd}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      scale={scale}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              planImage={planImage}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      axes={filteredAxes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              selectedAxisId={selectedAxisId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      showGrid={showGrid}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              axisBubbleSize={axisBubbleSize}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      activeFloor={activeFloor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              showPreviousFloor={showPreviousFloor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      mode={mode}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              roundCornerFirstWallId={roundCornerFirstWallId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      roundedCorners={roundedCorners}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              pendingRoundedCorner={pendingRoundedCorner}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      selectedRoundedCornerId={selectedRoundedCornerId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              joinWallsPendingIds={joinWallsPendingIds}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      contourHighlightIds={contourHighlightIds}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* ✅ تمرير selectedElement هنا ضروري ليظهر التحديد الأخضر */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <ElementLayer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      columns={filteredColumns}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              windows={filteredWindows}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      doors={filteredDoors}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              openings={filteredOpenings}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      selectedElement={selectedElement} 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              walls={walls}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      view={view}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width={width}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      height={height}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              scale={scale}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ElementEditLayer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        selected={selectedElement}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                columns={filteredColumns}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        windows={filteredWindows}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                doors={filteredDoors}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        walls={walls}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                view={view}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        width={width}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                height={height}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {filteredTexts.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TextLayer texts={filteredTexts} view={view} width={width} height={height} selectedId={selectedTextId} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TextEditLayer selectedText={filteredTexts.find(t => t.id === selectedTextId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {filteredDimensions.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <DimensionLayer dimensions={filteredDimensions} view={view} width={width} height={height} fontSize={dimensionFontSize} selectedId={selectedDimId} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <RegionLayer regions={filteredRegions} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <StairLayer stairs={filteredStairs} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <StairEditLayer selectedStair={filteredStairs.find(s => s.id === selectedStairId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <NorthArrowLayer northArrows={northArrows} view={view} width={width} height={height} selectedId={selectedNorthArrowId} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <NorthArrowEditLayer selectedArrow={northArrows.find(a => a.id === selectedNorthArrowId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ClipFrameLayer clipFrames={clipFrames} view={view} width={width} height={height} selectedId={selectedClipFrameId} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ClipFrameEditLayer selectedClipFrame={clipFrames.find(f => f.id === selectedClipFrameId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <AxisEditLayer selectedAxis={filteredAxes.find(a => a.id === selectedAxisId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <StairElementLayer stairElements={filteredStairElements} view={view} width={width} height={height} scale={scale} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <StairElementEditLayer selectedElement={filteredStairElements.find(el => el.id === selectedStairElementId) ?? null} view={view} width={width} height={height} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });